def solve(inputs: dict) -> float:
    def pick(*names):
        for name in names:
            if name in inputs:
                return inputs[name]
        raise KeyError(names[0])

    s = int(pick('s', 'x', 'X', 'start', 'initial', 'seed'))
    a = int(pick('a', 'multiplier', 'mul'))
    c = int(pick('c', 'increment', 'add'))
    m = int(pick('m', 'mod', 'modulus'))
    n = int(pick('n', 'steps', 'iterations', 'count', 'times', 'updates'))
    for _ in range(n):
        s = (a * s + c) % m
    return s

